/**
 * ClickPesa HMAC-SHA256 security utilities.
 *
 * Used for generating request checksums and verifying incoming webhook
 * signatures. Serialization is byte-compatible with the reference algorithm:
 *
 * 1. Recursively sort all object keys alphabetically at every nesting level.
 * 2. Serialize to compact JSON (no extra whitespace).
 * 3. Return the hex digest of `HMAC-SHA256(key, jsonString)`.
 */
export declare const SecurityManager: {
    /**
     * Generate a ClickPesa-compatible HMAC-SHA256 checksum for a payload.
     *
     * The payload must NOT already contain a `checksum` field.
     * Returns an empty string when the key is empty or undefined.
     */
    createChecksum(checksumKey: string | undefined | null, payload: Record<string, unknown>): string;
    /**
     * Verify an incoming ClickPesa webhook signature in constant time.
     *
     * @param signature value of the `X-ClickPesa-Signature` header.
     */
    verifyWebhook(checksumKey: string, payload: Record<string, unknown>, signature: string | undefined | null): boolean;
};
